-- T40 · Rohan's seeded consent world (DESIGN §5b "Who has my number"; CONFLICTS C-40).
-- Runs after `supabase db reset` (migrations + supabase/seed/*.sql generated by T03b's
-- seedmaps people/consents/family). The seed writes consents and number shares the
-- product's way, under Rohan's own JWT with tap ids, so Triggers 1 and 2 accept it.
begin;
create extension if not exists pgtap with schema extensions;
select plan(10);

select is(
  (select array_agg(ref order by ref) from app.consents where principal_user_id = 'bff1ee72-9910-5980-a875-96a9a00b24cf'),
  array['C-0902-01', 'C-1012-04', 'C-1012-05', 'C-1015-02', 'C-1018-11']::text[],
  'Rohan''s 5 consent refs'
);
select is(
  cardinality(app.number_holders('bff1ee72-9910-5980-a875-96a9a00b24cf')),
  3,
  '3 parties can reach Rohan'
);
select is(
  array(select h from unnest(app.number_holders('bff1ee72-9910-5980-a875-96a9a00b24cf')) as h order by 1),
  array[
    'd27c1409-5f1e-5918-965a-0629e13f407f', -- Orbis Land site office
    'dc8aac37-8b88-539c-97c6-597d5b873d4b', -- Meridian Habitat site office
    'ef484441-3db2-51ab-9e09-1c3773d1b69b'  -- Larkspur Realty (agent)
  ]::uuid[],
  'the holders are Orbis Land, Meridian Habitat''s site office and Larkspur Realty'
);
select results_eq(
  $$select s.ended_reason, s.ends_at from app.contact_shares s join app.consents c on c.id = s.consent_id where c.ref = 'C-0902-01'$$,
  $$values ('expired'::text, '2026-10-02 00:00+05:30'::timestamptz)$$,
  'the Meridian sales office share ended on 2 Oct 2026 and does not count'
);
select is(
  (select count(*)::int from app.relay_sessions
    where buyer_user_id = 'bff1ee72-9910-5980-a875-96a9a00b24cf' and closed_at is null and deal_active
      and recipient_org_id = 'a3789e36-f6a8-5e75-b050-79d39f37193d'),
  1,
  'the Northfield relay is open and is not a holder'
);
select ok(
  (select count(*) = 4 and bool_and(follow_type = 'watching') from app.follows where user_id = 'bff1ee72-9910-5980-a875-96a9a00b24cf'),
  'Rohan follows 4 phases, all watching'
);
select results_eq(
  $$select phone_masked, following_seen_at from app.profiles where id = 'bff1ee72-9910-5980-a875-96a9a00b24cf'$$,
  $$values ('+91 99••• ••318'::text, '2026-10-14 08:40+05:30'::timestamptz)$$,
  'Rohan''s profile: masked phone and his last look (14 Oct 2026, 8:40 am)'
);
select results_eq(
  $$select m.invite_code, m.status from app.family_members m join app.family_circles c on c.id = m.circle_id
     where c.owner_user_id = 'bff1ee72-9910-5980-a875-96a9a00b24cf' order by m.invite_code$$,
  $$values ('AH2-7KQ'::text, 'invited'::text), ('RC4-2MW', 'invited'), ('RC4-8TD', 'joined')$$,
  'Rohan''s circle: Meera joined (RC4-8TD), two open invites'
);

-- A 4th party (Northfield's site office) cannot get the number.
select set_config('request.jwt.claims', '{"sub":"bff1ee72-9910-5980-a875-96a9a00b24cf","role":"authenticated"}', true);
insert into app.consents (id, principal_user_id, purpose_code, recipient_kind, recipient_org_id, phase_id, notice_version, evidence)
values ('00000000-0000-4000-8000-000000400401', 'bff1ee72-9910-5980-a875-96a9a00b24cf', 'number_share', 'site_office',
        'a3789e36-f6a8-5e75-b050-79d39f37193d', '4da0daeb-835b-54d5-9c09-a23ee9cb4b36', 'Privacy notice v1.0, 1 Oct 2026', '{"tap_event_id":"t40-c4-4th"}');
select throws_ok(
  $$insert into app.contact_shares (consent_id, buyer_user_id, recipient_org_id, phase_id, number_shared)
    values ('00000000-0000-4000-8000-000000400401', 'bff1ee72-9910-5980-a875-96a9a00b24cf', 'a3789e36-f6a8-5e75-b050-79d39f37193d', '4da0daeb-835b-54d5-9c09-a23ee9cb4b36', true)$$,
  'PT409', 'cap_reached',
  'a 4th holder for Rohan fails, even with his own tap'
);

-- Meera (joined his circle) reads none of Rohan's consents (wall 2, temporary grant).
select set_config('request.jwt.claims', '', true);
grant usage on schema app to authenticated;
grant select on app.consents to authenticated;
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"de38ce39-c6cc-5c35-b8a7-ecc1a480ff58","role":"authenticated"}', true);
select is(
  (select count(*)::int from app.consents where principal_user_id = 'bff1ee72-9910-5980-a875-96a9a00b24cf'),
  0,
  'Meera, in Rohan''s circle, reads none of his consents'
);
reset role;

select * from finish();
rollback;
